use crate::aap::caps::types::{AgentResponse, LlmError};
use crate::aap::caps::{kb_read, tool_llm};

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The `requires len(question) <= 512` precondition is discharged by the
        // caller; every input we are handed already satisfies it.
        let system = "You are a customer support agent. Answer the user's \
                      question using the provided knowledge. If you need more \
                      material you may request the `lookup` tool with a search \
                      query; otherwise reply with the answer text.";

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\n\nKnowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // Bounded tool-orchestration loop. The model either answers (`text`) or
        // asks for a tool (`call`); the only tool this node is granted is
        // `lookup`, backed by the read-only knowledge-base handle.
        const MAX_ROUNDS: usize = 4;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nTool `lookup` results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        // Any other tool is outside this node's authority.
                        return ResponseResult::Error(LlmError {
                            message: format!(
                                "model requested unavailable tool `{}`",
                                req.tool
                            ),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge".to_string(),
        })
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
